// fish: backend + emitter (fish 3.4+; uses `string collect -N`, `math -s0`).
#include "shell.hpp"
#include "emit_dialect.hpp"
#include <set>
namespace {
using namespace forge::script;
std::string fq(const std::string& s) { std::string o = "'"; for (char c : s) { if (c == '\'' || c == '\\') o += '\\'; o += c; } return o + "'"; }
struct fish_dialect : block_dialect {
    std::set<std::string> need;
    std::string header() override {
        std::string h = "#!/usr/bin/env fish\n# generated by `forge script --emit fish`; runs without FORGE\n";
        if (need.count("platform")) h += "function _platform\n    switch (uname -s)\n        case Linux\n            if set -q ANDROID_ROOT; echo android; else; echo linux; end\n        case Darwin\n            echo macos\n        case FreeBSD\n            echo freebsd\n        case 'MINGW*' 'MSYS*' 'CYGWIN*' Windows_NT\n            echo windows\n        case '*'\n            echo other\n    end\nend\n";
        return h;
    }
    std::string s_lit(const std::string& s) override { return fq(s); }
    std::string ref(const std::string& n, ety t, bool) override { return t == ety::Int ? "$" + n : "\"$" + n + "\""; }
    std::string arith(char op, const std::string& a, const std::string& b) override { std::string o(1, op); if (op == '*') o = "'*'"; return "(math -s0 -- " + a + " " + o + " " + b + ")"; }
    std::string neg(const std::string& a) override { return "(math -s0 -- 0 - " + a + ")"; }
    std::string concat(const std::vector<std::string>& p) override { std::string o; for (auto& x : p) o += x; return o; }
    std::string i2s(const std::string& i) override { return i; }
    std::string s2i(const std::string& s) override { return "(math -s0 -- " + s + ")"; }
    std::string slen(const std::string& s) override { return "(string length -- " + s + ")"; }
    std::string cmp(const std::string& op, const std::string& a, const std::string& b, bool ints) override {
        static const std::pair<const char*, const char*> io[] = {{"==", "-eq"}, {"!=", "-ne"}, {"<", "-lt"}, {"<=", "-le"}, {">", "-gt"}, {">=", "-ge"}};
        if (ints) for (auto& [o, t] : io) if (op == o) return "test " + a + " " + t + " " + b;
        if (op == "==") return "test " + a + " = " + b;
        if (op == "!=") return "test " + a + " != " + b;
        no("string ordering with " + op);
    }
    std::string c_and(const std::string& a, const std::string& b) override { return "begin; " + a + "; and " + b + "; end"; }
    std::string c_or(const std::string& a, const std::string& b) override { return "begin; " + a + "; or " + b + "; end"; }
    std::string c_not(const std::string& a) override { return "not begin; " + a + "; end"; }
    std::string c_bool(bool v) override { return v ? "true" : "false"; }
    void let(const std::string& n, const std::string& v, ety, bool global, bool decl) override {
        if (global || !cx->in_fn) L("set -g " + n + " " + v);
        else L(std::string(decl ? "set -l " : "set ") + n + " " + v);
    }
    void print(const std::string& v, bool nl, bool err) override { L(std::string("printf '%s") + (nl ? "\\n" : "") + "' " + v + (err ? " >&2" : "")); }
    void if_(const std::string& c) override { open("if " + c); }
    void else_() override { mid("else"); }
    void end_if() override { close("end"); }
    void while_(const std::string& c) override { open("while " + c); }
    void end_while() override { close("end"); }
    void for_(const std::string& v, const std::vector<std::string>& items) override { std::string s = "for " + v + " in"; for (auto& i : items) s += " " + i; open(s); }
    void end_for() override { close("end"); }
    void brk() override { L("break"); }
    void cont() override { L("continue"); }
    void fn_(const std::string& name, const std::vector<std::string>& ps) override {
        open("function " + name);
        for (std::size_t i = 0; i < ps.size(); ++i) L("set -l " + ps[i] + " $argv[" + std::to_string(i + 1) + "]");
    }
    void end_fn() override { close("end"); }
    void ret(const std::string& v) override { if (!v.empty()) L("set -g _r " + v); L("return 0"); }
    std::string call(const std::string& name, const std::vector<std::string>& a, bool want, ety rt) override {
        std::string s = name; for (auto& x : a) s += " " + x;
        L(s);
        if (!want) return "";
        auto t = cx->tmp(); let(t, "\"$_r\"", rt, !cx->in_fn, true); return ref(t, rt, !cx->in_fn);
    }
    void exit_(const std::string& c) override { L("exit " + c); }
    std::string env(const std::string& n, const std::string& d) override {
        std::string name; if (!lit_name(n, '\'', name)) no("a dynamic environment variable name");
        auto t = cx->tmp(); let(t, d, ety::Str, !cx->in_fn, true);
        if_("set -q " + name); let(t, "\"$" + name + "\"", ety::Str, !cx->in_fn, false); end_if();
        return "\"$" + t + "\"";
    }
    void setenv(const std::string& n, const std::string& v) override { std::string name; if (!lit_name(n, '\'', name)) no("a dynamic environment variable name"); L("set -gx " + name + " " + v); }
    std::string test_path(const std::string& p, char k) override { return std::string("test -") + k + " " + p; }
    void mkdir(const std::string& p) override { L("mkdir -p -- " + p); }
    void remove(const std::string& p) override { L("rm -rf -- " + p); }
    void write(const std::string& p, const std::string& s, bool app) override { L("printf '%s' " + s + (app ? " >> " : " > ") + p); }
    std::string read(const std::string& p) override { return "(cat -- " + p + " | string collect -N)"; }
    std::string cwd() override { return "(pwd -P)"; }
    std::string platform() override { need.insert("platform"); return "(_platform)"; }
    void run(const std::string& cmd, const std::string& o, const std::string& c, bool host) override {
        bool g = !cx->in_fn;
        if (host) let(o, "(begin; eval " + cmd + "; printf '\\x1c%d' $status; end | string collect -N)", ety::Str, g, false);
        else let(o, "(sh -c " + fq(sh_wrapper()) + " _ " + cmd + " | string collect -N)", ety::Str, g, false);
        L("printf '%s' \"$" + o + "\" | read -z -d \\x1c " + std::string(g ? "-g " : "") + o + " " + c);
    }
    std::string sh_quote(const std::string& v) override { return "\"'\"(string replace -a \"'\" \"'\\\\''\" -- " + v + " | string collect)\"'\""; }
};
} // namespace
void forge_shell_register_fish(forge::script::shell_registry& r) {
    forge::script::shell_backend b; b.name = "fish"; b.exes = {"fish"}; b.family = "fish"; b.golden_tested = true;
    b.argv = forge::script::shellq::dash_c;
    b.quote = fq;
    b.emitter = [] { return std::make_unique<fish_dialect>(); }; b.emit_ext = ".fish"; b.emit_tested = true;
    r.add(std::move(b));
}
